#pragma once
static const char* defaultConfig = R"SLSCFG(#Example AppIds Config for those not familiar with YAML:
#AppIds:
#  - 440
#  - 730
#Take care of not messing up your spaces! Otherwise it won't work

#Example of DlcData:
#DlcData:
#  AppId:
#    FirstDlcAppId: "Dlc Name"
#    SecondDlcAppId: "Dlc Name"

#Example of DenuvoGames:
#DenuvoGames:
#  SteamId:
#    -  AppId1
#    -  AppId2

#Example of FakeAppIds:
#FakeAppIds:
#  AppId1: FakeAppId1
#  AppId2: FakeAppId2

#Disables Family Share license locking for self and others
DisableFamilyShareLock: yes

#Locally unlocks Steam areas restricted by parental controls. Requires restart.
DisableParentalRestrictions: no

#Switches to whitelist instead of the default blacklist
UseWhitelist: no

#List of AppIds to ex-/include. Either specify each DLC you want to in-/exclude individually
#or add the DLC's parent AppId (the Game's one) to allow unlocking all of their child AppIds
AppIds:


#DO NOT ADD APPIDS HERE. Recent slsteam-moon versions read the game list
#directly from ~/.steam/steam/config/stplug-in. To add AppIDs manually
#(without relying on stplug-in), use ~/.config/SLSsteam/luaappids.yaml.
#This section is kept only for backward compatibility and will be removed
#in future versions.
AdditionalApps:

#Extra Data for Dlcs belonging to a specific AppId. Only needed
#when the App you're playing is hit by Steams 64 DLC limit
DlcData:

#Used to retrieve ProductInfo from Steam servers for some games
AppTokens:

#Legacy CD keys required by some games
#Unless explicitly specified SLSsteam will generate a random 4 * 4 key using A-Z + 0-9 seeded by your accountId + appId
#If you want to delete injected CD keys delete cdk_[number] from your localconfig.vdf
CDKeys:

#Fake Steam being offline for specified AppIds. Same format as AppIds
FakeOffline:

#Change AppIds of games to enable networking features
#Use 0 as a key to set for all unowned Apps
#Do not run multiple apps under the same AppId simultaneously! It's possible but
#will most likely cause undefined behaviour
#The last app you launched will be used as the real appId
FakeAppIds:

#Override Depot manifest IDs
#Use this to download older game versions or to lock a game to a specific version
ManifestIds:

#Never download these depots
DepotBlacklist:

#Custom ingame statuses. Set AppId to 0 to disable
IdleStatus:
  AppId: 0
  Title: ""

#Override game titles. Only works with owned appIds! For injected appIds use either UnownedStatus or combine them with FakeAppIds
GameTitles:

#Override purchase time stamps
SubscriptionTimestamps:

#Blocks games from unlocking on wrong accounts
DenuvoGames:

#Overrides your SteamId an app sees. Only needed when the automatic SteamId spoofing
#fails (some games do call GetSteamId before they request your ticket)
#Also can be used to workaround locked saves
#Either set to SteamId or to 0 to use the SteamId in the cached AppOwnershipTicket
SteamIdOverride:

#How many recent reviewers of a game to try as its achievement-schema owner when
#no AchievementOwnerId is set or it cannot read that game's schema. They are
#looked up in the background (one store request per game, at most every 10
#minutes), so no page waits for it; the next schema request uses them. What
#worked is kept in cache/achievement_owners.txt for later sessions. 0 turns the
#lookup off.
MaxSchemaTries: 10

#Override commands right in CUser::SpawnGame. Use %command% as special string, just like in Steam itself
#Two special keys exist:
#4294967294: Sets the launch option for all managed apps without a license of your own
#4294967295: Sets the launch option for all apps (the key above wins for those apps)
LaunchOptions:


#Toggles notifications via notify-send
Notifications: yes


#Notify when SLSsteam is done initializing
NotifyInit: yes

#Enable sending commands to SLSsteam via $XDG_RUNTIME_DIR/SLSsteam/api
#(~/.cache/SLSsteam/api without XDG_RUNTIME_DIR), a 0600 file in a 0700 folder
API: no

#Enable the usage of Lua plugins from the plugins subdirectory
#SLSsteam plugins can run arbitrary code! So only run plugins you trust
Plugins: no

#Disable cloud saves for unlocked games. Default "no" so CloudRedirect (shipped
#with this stack) can sync saves to your own provider. Set to "yes" if you are
#NOT using CloudRedirect, to avoid a doomed cloud sync that Steam rejects.
DisableCloud: no

#Keep managed games on the latest build. Default "yes" (games auto-update).
#Set to "no" to lock every managed game to its currently installed build (like
#LuaTools' "Auto Update Apps" toggle). Builds you pin per game still apply.
AutoUpdateApps: yes

# Share short-lived manifest request codes for depots this account really owns.
# The wanted list is downloaded from the archive; only matching depots are sent.
# Set Enabled: no to disable both active requests and passive capture.
Donate:
  Enabled: yes
  Url: "https://manifest.luastools.xyz"
  IntervalSecs: 30
  WantedRefreshSecs: 300
  MaxMintsPerCycle: 25
  MinMintIntervalMs: 2000
  MaxMintsPerSession: 0 # 0 means no session cap

# Inject every storefront-advertised DLC into package 0. Keep disabled by
# default; content-backed DLC is still injected automatically.
InjectAllAdvertisedDlc: no

#Show achievements for unowned games. Steam only returns a game's achievement
#schema to an account that owns it, so the schema is sourced from an owner (see
#MaxSchemaTries). Set to "no" to disable achievement schema spoofing.
Achievements: yes

#Account (SteamID64) asked for a game's achievement schema when AchievementOwners
#has no entry for it. 0 = none. Without one, or when it cannot read the schema,
#recent reviewers are tried (see MaxSchemaTries). Only the public schema is read;
#no account is signed in to.
AchievementOwnerId: 0

#Per-game override of the achievement-schema source account. Same shape as
#FakeAppIds:
#AchievementOwners:
#  AppId: SteamID64
AchievementOwners:

# Local pattern cache keyed by GNU build-id, module size, and mtime. Each
# cached signature is rechecked before an address is accepted.
PatternCache: yes

# Refresh existing appinfo buffers from the PICS worker after Steam starts.
# Apps without a complete cache still use the synchronous PICS fallback.
AsyncProvision: yes

# Safety valve for accidental bulk copies into config/stplug-in, NOT a limit on
# how many games you can have. Steam's own license and appinfo reconciliation
# stalls for minutes when tens of thousands of scripts are dropped in at once,
# so only this many scripts are activated per session.
#
# The default sits far above any realistic library, and priority always goes to
# luaappids.yaml entries, games already installed on disk, and games already
# active in the session. Scripts beyond the limit are NEVER deleted: they stay
# on disk and activate as soon as the set shrinks or you raise this value.
# Set to 0 to disable the limit entirely.
MaxManagedApps: 4096

#Disable updates for AppIds on AdditionalApps
#Only works for unowned games, since those do not get any depots from CUserAppManager::BuildDepotDependency.
#For owned games use ManifestIds
DisableUpdates: yes

#Changes your Persona's Name clientsidedly
FakeName: ""

#Changes your account's E-Mail clientsided. Leave blank to disable
FakeEmail: ""

#Changes your wallet's balance clientsidedly. 0 to turn off
FakeWalletBalance: 0

#The log is ~/.SLSsteam.log. Once it reaches 8 MiB it is moved to
#~/.SLSsteam.log.1 when Steam starts; the 3 newest old logs are kept.
#Log levels:
#Once = 0
#Debug = 1
#Info = 2
#NotifyShort = 3
#NotifyLong = 4
#Warn = 5
#None = 6
LogLevel: 2

#Dump all used IClientInterfaceMaps
DumpClientInterfaces: no

#Logs all calls to Steamworks (this makes the logfile huge! Only useful for debugging/analyzing
ExtendedLogging: no)SLSCFG";
